const input=$json.body??$json;
const arr=v=>Array.isArray(v)?v:[];
const truthy=v=>v===true||v==="true"||v===1||v==="1";
const blockers=arr(input.blockers);
const outcome=input.final_closing_outcome??{};
const execution=input.execution??{};
const funding=input.funding??{};
const title=input.title??{};
const identityComplete=Boolean(input.deal_id&&input.lead_id&&input.property_id&&input.close_id);
const outcomeReady=truthy(input.final_closing_outcome_ready)||["ready","final_closing_outcome_ready","completed"].includes(String(outcome.status||"").toLowerCase());
const executedAgreement=truthy(input.executed_agreement)||["executed","signed","fully_executed"].includes(String(input.agreement_status||"").toLowerCase());
const executionComplete=truthy(input.execution_complete)||["completed","closed","executed"].includes(String(execution.status||"").toLowerCase());
const fundingVerified=truthy(input.funding_verified)||["verified","funded","complete"].includes(String(funding.status||"").toLowerCase());
const titleVerified=truthy(input.title_verified)||["verified","clear","complete"].includes(String(title.status||"").toLowerCase());
const closingDateValid=Boolean(input.actual_closing_date||input.closing_date)&&!Number.isNaN(new Date(input.actual_closing_date||input.closing_date).getTime());
const gross=Number(input.gross_profit??input.assignment_fee??input.gross_revenue);
const costs=Number(input.closing_costs??input.total_costs??0);
const net=Number(input.net_profit??(Number.isFinite(gross)?gross-costs:NaN));
const profitInputsValid=Number.isFinite(gross)&&Number.isFinite(costs)&&Number.isFinite(net);
const blockersClear=blockers.length===0;
const verifiedClose=identityComplete&&outcomeReady&&executedAgreement&&executionComplete&&fundingVerified&&titleVerified&&closingDateValid&&profitInputsValid&&blockersClear;

let status="close_verification_required",nextWorkflow="WF-283",humanReview=true;
if(!identityComplete){status="blocked_missing_identity";nextWorkflow="WF-126";}
else if(!outcomeReady){status="final_outcome_not_ready";nextWorkflow="WF-282";}
else if(!executedAgreement||!executionComplete){status="execution_evidence_missing";nextWorkflow="WF-282";}
else if(!fundingVerified||!titleVerified){status="funding_or_title_unverified";nextWorkflow="WF-282";}
else if(!closingDateValid||!profitInputsValid||!blockersClear){status="profit_or_close_inputs_invalid";nextWorkflow="WF-126";}
else{status="verified_close_ready";nextWorkflow="WF-284";}

return [{json:{...input,workflow:"WF-283",workflow_name:"Final Closing Outcome → Verified Close, Profit Reconciliation & CRM Closeout Controller",status,verified_close:{identity_complete:identityComplete,final_outcome_ready:outcomeReady,executed_agreement:executedAgreement,execution_complete:executionComplete,funding_verified:fundingVerified,title_verified:titleVerified,actual_closing_date_valid:closingDateValid,gross_profit:gross,closing_costs:costs,net_profit:net,profit_inputs_valid:profitInputsValid,blockers_clear:blockersClear,verified:verifiedClose},next_workflow:nextWorkflow,human_review_required:humanReview,routing_reason:status,audit:{event_type:"verified_close_profit_reconciliation",idempotency_key:input.idempotency_key||`wf-283:${input.deal_id||"unknown"}:${input.close_id||"none"}:${input.version||1}`}}}];
